<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { AxiosError } from 'axios'
import AppWindowDialog from '@/components/common/AppWindowDialog.vue'
import { fetchFinishedRecords,fetchFinishedRecord } from '@/api/finishedReceipts'
import { fetchFinishedGoodsFilterOptions } from '@/api/inventory'
import type { FinishedRecord } from '@/types/finishedReceipts'
import type { MaterialReceivingOptions } from '@/types/inventory'
const route=useRoute(),router=useRouter(),q=ref(''),warehouse=ref(''),zone=ref(''),source=ref(''),page=ref(1),pageSize=ref(50),total=ref(0)
const rows=ref<FinishedRecord[]>([]),options=ref<MaterialReceivingOptions>({warehouses:[],zones:[]}),loading=ref(false),error=ref(''),detail=ref<FinishedRecord>(),visible=ref(false),detailLoading=ref(false),detailError=ref('')
const planFilter=ref(String(route.query.schedule_product_id||''));let sequence=0,detailSequence=0
const msg=(e:unknown)=>e instanceof AxiosError?e.response?.data?.error?.message||'记录读取失败，请重试。':'记录读取失败，请重试。'
async function load(){const current=++sequence;loading.value=true;error.value='';try{const result=await fetchFinishedRecords({q:q.value,warehouse_id:warehouse.value||undefined,zone_id:zone.value||undefined,source:source.value,page:page.value,page_size:pageSize.value,schedule_product_id:planFilter.value||undefined});if(current!==sequence)return;rows.value=result.items;total.value=result.total}catch(e){if(current===sequence){error.value=msg(e);rows.value=[]}}finally{if(current===sequence)loading.value=false}}
function search(){page.value=1;void load()}
async function show(id:string){const current=++detailSequence;visible.value=true;detail.value=undefined;detailError.value='';detailLoading.value=true;try{const value=await fetchFinishedRecord(id);if(current===detailSequence)detail.value=value}catch(e){if(current===detailSequence)detailError.value=msg(e)}finally{if(current===detailSequence)detailLoading.value=false}}
function clearPlan(){planFilter.value='';void router.replace({query:{tab:'records'}});search()}
onMounted(()=>{void load();void fetchFinishedGoodsFilterOptions().then(value=>options.value=value).catch(e=>error.value=msg(e))})
</script>
<template>
 <section class="fg-records-panel">
 <div class="fg-filters"><ElInput v-model="q" clearable placeholder="搜索入库单号、生产单号、品号或品名" @keyup.enter="search" @clear="search"/><ElSelect v-model="warehouse" clearable placeholder="全部仓库" @change="zone='';search()"><ElOption v-for="w in options.warehouses" :key="w.id" :value="w.id" :label="w.warehouse_name"/></ElSelect><ElSelect v-model="zone" clearable placeholder="全部库区" @change="search"><ElOption v-for="z in options.zones.filter(v=>!warehouse||v.warehouse===warehouse)" :key="z.id" :value="z.id" :label="z.zone_name"/></ElSelect><ElSelect v-model="source" clearable placeholder="全部来源" @change="search"><ElOption label="装配入库" value="ASSEMBLY"/><ElOption label="生产入库" value="PRODUCTION_ORDER"/><ElOption label="样品入库" value="SAMPLE_INVENTORY"/></ElSelect><ElButton @click="search">查询</ElButton></div>
 <div class="fg-toolbar"><span class="fg-muted">{{planFilter?'当前订单产品的全部入库记录':'按原单逐笔保留来源；点击查看打开详情弹窗'}}</span><ElButton v-if="planFilter" link @click="clearPlan">查看全部</ElButton><ElButton class="fg-refresh" @click="load">刷新</ElButton></div><ElAlert v-if="error" :title="error" type="error" :closable="false"/>
 <div class="fg-table-card" v-loading="loading"><div class="fg-table-scroll"><table class="fg-table"><colgroup><col v-for="(width,i) in [155,105,150,105,150,160,80,90,60,90,65,90,105,90,95]" :key="i" :style="{width:width+'px'}"></colgroup><thead><tr><th v-for="name in ['入库单号','入库来源','生产单号','品号','品名','规格','颜色','入库数量','单位','仓库','库区','库位','入库日期','状态','操作']" :key="name">{{name}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td :title="r.receipt_number">{{r.receipt_number}}</td><td><span :class="['fg-tag',r.source_type==='SAMPLE_INVENTORY'?'info':'']">{{r.source_type_display}}</span></td><td :title="r.task_number_snapshot">{{r.task_number_snapshot||'—'}}</td><td>{{r.product_number_snapshot||'—'}}</td><td :title="r.product_name_snapshot">{{r.product_name_snapshot}}</td><td :title="r.specification_snapshot">{{r.specification_snapshot||'—'}}</td><td>{{r.actual_color||'—'}}</td><td class="num">{{r.received_quantity}}</td><td>{{r.unit_name}}</td><td>{{r.warehouse_name}}</td><td>{{r.zone_name}}</td><td>{{r.location_number}}</td><td>{{r.receipt_date}}</td><td><span class="fg-tag success">已入库</span></td><td><ElButton link type="primary" @click="show(r.id)">查看</ElButton></td></tr></tbody></table><div class="fg-empty" v-if="!loading&&!rows.length">暂无符合条件的入库记录</div></div><footer class="fg-pager"><span>共 {{total}} 条</span><ElPagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[20,50,100]" layout="sizes, prev, pager, next" @current-change="load" @size-change="search"/></footer></div>
 <AppWindowDialog v-model="visible" title="成品入库 · 来源详情" :width="1180" :height="660" class="fg-window" destroy-on-close><div v-loading="detailLoading"><ElAlert v-if="detailError" :title="detailError" type="error" :closable="false"/><template v-if="detail"><div class="fg-detail-title"><b>{{detail.receipt_number}}</b><span class="fg-tag">{{detail.source_type_display}}</span><span class="fg-tag success">已入库</span></div><dl class="fg-detail-fields"><div v-for="([k,v]) in [['生产单号',detail.task_number_snapshot],['订单号',detail.order_number_snapshot],[detail.source_type==='SAMPLE_INVENTORY'?'样品来源单':'装配计划',detail.source_type==='SAMPLE_INVENTORY'?detail.source_document_number:detail.schedule_number],['收货日期',detail.receipt_date],['成品仓 / 库区',detail.warehouse_name+' / '+detail.zone_name],['库位',detail.location_number],['入库人',detail.received_by_name],['供应商',detail.supplier_name],['备注',detail.remark]]" :key="String(k)"><dt>{{k}}</dt><dd>{{v||'—'}}</dd></div></dl><h2 class="fg-detail-heading">成品明细</h2><div class="fg-table-card"><table class="fg-table compact"><thead><tr><th v-for="h in ['品号','品名','规格','颜色','数量','单位']" :key="h">{{h}}</th></tr></thead><tbody><tr><td>{{detail.product_number_snapshot}}</td><td>{{detail.product_name_snapshot}}</td><td :title="detail.specification_snapshot">{{detail.specification_snapshot}}</td><td>{{detail.actual_color}}</td><td>{{detail.received_quantity}}</td><td>{{detail.unit_name}}</td></tr></tbody></table></div><div class="fg-detail-summary"><span>每箱数量：{{detail.quantity_per_box??'未计算'}}</span><span>整箱数：{{detail.box_count??'未计算'}}</span><span>尾数：{{detail.tail_quantity??'未计算'}}</span><span>占用箱位：{{detail.occupied_box_slots??'未计算'}}</span></div><p v-if="detail.received_after!=null" class="fg-helper">本单入库前 {{detail.received_before}}，本次 {{detail.received_quantity}}，入库后累计 {{detail.received_after}} {{detail.unit_name}}；该订单产品上限 {{detail.maximum_receivable}} {{detail.unit_name}}。</p></template></div><template #footer><ElButton @click="visible=false">关闭</ElButton></template></AppWindowDialog>
 </section>
</template>
